ss/bootstrap.min.css\" rel=\"stylesheet\" type=\"text/css\" />\n        <link href=\"http://localhost:8081/course/public/assets/css/icons.min.css\" rel=\"stylesheet\" type=\"text/css\" />\n        <link href=\"http://localhost:8081/course/public/assets/css/app.min.css\" rel=\"stylesheet\" type=\"text/css\" />\n    </head>\n    \n    <body>\n    <div class=\"container-xxl\">\n        <div class=\"row vh-100 d-flex justify-content-center\">\n            <div class=\"col-12 align-self-center\">\n                <div class=\"card-body\">\n                    <div class=\"row\">\n                        <div class=\"col-lg-4 mx-auto\">\n                            <div class=\"card\">\n                                <div class=\"card-body p-0 bg-black auth-header-box rounded-top\">\n                                    <div class=\"text-center p-3\">\n                                        <a href=\"index.html\" class=\"logo logo-admin\">\n                                            <img src=\"http://localhost:8081/course/public/assets/images/logo-sm.png\" height=\"50\" alt=\"logo\" class=\"auth-logo\">\n                                        </a>\n                                        <h4 class=\"mt-3 mb-1 fw-semibold text-white fs-18\">Aplikasi Membership Sindikasi</h4>   \n                                        <p class=\"text-muted fw-medium mb-0\">Sign in to continue</p>  \n                                    </div>\n                                </div>\n                                <div class=\"card-body pt-0\">                    \n                                                        \n                                    <form class=\"my-4\" action=\"http://localhost:8081/course/auth/login\" method=\"POST\">            \n                                        <div class=\"form-group mb-2\">\n                                            <label class=\"form-label\" for=\"username\">Username</label>\n                                            <input type=\"text\" class=\"form-control\" id=\"username\" name=\"username\" placeholder=\"Enter username\">                               \n                                        </div><!--end form-group--> \n            \n                                        <div class=\"form-group\">\n                                            <label class=\"form-label\" for=\"userpassword\">Password</label>                                            \n                                            <input type=\"password\" class=\"form-control\" name=\"password\" id=\"userpassword\" placeholder=\"Enter password\">                            \n                                        </div><!--end form-group--> \n            \n                                        <div class=\"form-group row mt-3\">\n                                            <!-- <div class=\"col-sm-6\">\n                                                <div class=\"form-check form-switch form-switch-success\">\n                                                    <input class=\"form-check-input\" type=\"checkbox\" id=\"customSwitchSuccess\">\n                                                    <label class=\"form-check-label\" for=\"customSwitchSuccess\">Remember me</label>\n                                                </div>\n                                            </div> --><!--end col--> \n                                            <div class=\"col-sm-6 text-end\">\n                                                <a href=\"auth-recover-pw.html\" class=\"text-muted font-13\"><i class=\"dripicons-lock\"></i> Forgot password?</a>                                    \n                                            </div><!--end col--> \n                                        </div><!--end form-group--> \n            \n                                        <div class=\"form-group mb-0 row\">\n                                            <div class=\"col-12\">\n                                                <div cl